const input = $input.first().json || {};
const isWebhook = Boolean(input.body && typeof input.body === 'object');

function firstDefined(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return undefined;
}

function toBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  const text = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'y'].includes(text)) return true;
  if (['false', '0', 'no', 'n'].includes(text)) return false;
  return fallback;
}

function toInt(value, fallback, min, max) {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(min, Math.min(max, parsed));
}

function normalizeScrollBehavior(value) {
  const text = String(value || '').trim().toLowerCase();
  return text === 'fixed' ? 'fixed' : 'natural';
}

function normalizeBrowserChannel(value) {
  const text = String(value || '').trim().toLowerCase();
  return text === 'edge' || text === 'msedge' || text === 'microsoft-edge' ? 'edge' : 'chrome';
}

function normalizeBrowserControlMode(value) {
  return String(value || '').trim() === 'edgeProfileMirror' ? 'edgeProfileMirror' : 'persistentContext';
}

function normalizeBrowserRunModeInput(value) {
  const text = String(value || '').trim().toLowerCase();
  if (text === 'headless' || text === 'headed') return text;
  return 'auto';
}

function sanitizeProfileDirectory(value) {
  const text = String(value || '').trim();
  if (!text || /[\\/:*?"<>|\x00-\x1F]/.test(text) || text === '.' || text === '..') return '';
  return text.slice(0, 80);
}

function normalizePath(value) {
  let result = String(value || '').trim();
  if ((result.startsWith('"') && result.endsWith('"')) || (result.startsWith("'") && result.endsWith("'"))) {
    result = result.slice(1, -1).trim();
  }
  result = result.replace(/\\+/g, '/').replace(/^([A-Za-z]:)\/+/, '$1/');
  while (result.length > 1 && result.endsWith('/') && !/^[A-Za-z]:\/$/.test(result)) result = result.slice(0, -1);
  return result;
}

function isAbsolutePath(value) {
  const normalized = normalizePath(value);
  return /^[A-Za-z]:\//.test(normalized) || normalized.startsWith('/');
}

function cleanName(value, fallback = 'product') {
  const cleaned = String(value || '')
    .trim()
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
    .replace(/[. ]+$/g, '')
    .replace(/\s+/g, ' ');
  return cleaned || fallback;
}

function joinPortable(root, ...segments) {
  const base = normalizePath(root).replace(/\/+$/, '');
  const suffix = segments
    .map((segment) => String(segment || '').replace(/^\/+|\/+$/g, ''))
    .filter(Boolean)
    .join('/');
  return normalizePath(suffix ? base + '/' + suffix : base);
}

function extractGoodsId(productUrl) {
  try {
    const u = new URL(productUrl);
    return u.searchParams.get('goods_id') || u.searchParams.get('goodsId') || '';
  } catch (error) {
    const match = String(productUrl || '').match(/[?&](?:goods_id|goodsId)=([^&#]+)/);
    return match ? decodeURIComponent(match[1]) : '';
  }
}

const body = input.body && typeof input.body === 'object' ? input.body : {};
