function normalizePath(value) {
  let text = String(value || '').trim().replace(/\\+/g, '/').replace(/^([A-Za-z]:)\/+/, '$1/');
  while (text.length > 1 && text.endsWith('/') && !/^[A-Za-z]:\/$/.test(text)) text = text.slice(0, -1);
  return /^[A-Za-z]:\//.test(text) ? text.toLowerCase() : text;
}

function readMetadataFallback() {
  const expectedPath = String(upstream.expectedMetadataPath || '').trim();
  const expectedOutputDir = String(upstream.expectedOutputDir || '').trim();
  if (!expectedPath || !expectedOutputDir) throw new Error('Expected metadata path is unavailable.');
  const fs = require('fs');
  if (!fs.existsSync(expectedPath)) throw new Error('Expected metadata file does not exist: ' + expectedPath);
  const metadata = JSON.parse(fs.readFileSync(expectedPath, 'utf8'));
  const params = metadata && typeof metadata.params === 'object' ? metadata.params : {};
  const result = metadata && typeof metadata.result === 'object' ? metadata.result : null;
  if (!result) throw new Error('Metadata does not contain a result object.');
  const mismatches = [];
  if (String(params.SKU || '') !== String(upstream.SKU || '')) mismatches.push('SKU');
  if (String(params.goodsId || '') !== String(upstream.goodsId || '')) mismatches.push('goodsId');
  if (String(params.n8nExecutionId || '') !== String(upstream.n8nExecutionId || '')) mismatches.push('n8nExecutionId');
  if (String(result.SKU || '') !== String(upstream.SKU || '')) mismatches.push('result.SKU');
  if (String(result.goodsId || '') !== String(upstream.goodsId || '')) mismatches.push('result.goodsId');
  if (normalizePath(result.outputDir) !== normalizePath(expectedOutputDir)) mismatches.push('result.outputDir');
  if (normalizePath(result.metadataPath) !== normalizePath(expectedPath)) mismatches.push('result.metadataPath');
  if (mismatches.length) throw new Error('Metadata identity mismatch: ' + mismatches.join(', ') + '.');
  return result;
}

