const stitchErrors = Array.isArray(parsed.errors) ? parsed.errors.filter(Boolean) : [];
const stitchWarnings = Array.isArray(parsed.warnings) ? parsed.warnings.filter(Boolean) : [];
warnings.push(...stitchWarnings);
if (parsed.skipped && stitchErrors.length) warnings.push(...stitchErrors);

const nonFatalPixelLimit = isVerifiedNonFatalPixelLimit(parsed);
const shouldFailWorkflow = !parsed.success
  && !parsed.skipped
  && !nonFatalPixelLimit
  && Boolean(original.success)
  && Number(original.detailImageCount || 0) > 0;
if (shouldFailWorkflow) errors.push(...stitchErrors);

return [{
  json: {
    ...original,
    success: shouldFailWorkflow ? false : Boolean(original.success),
    status: shouldFailWorkflow ? 'detail_long_image_failed' : String(original.status || (original.success ? 'success' : 'internal_error')),
    httpStatus: shouldFailWorkflow ? 500 : Number(original.httpStatus || (original.success ? 200 : 500)),
    errors,
    warnings,
    detailLongImageSuccess: Boolean(parsed.success),
    detailLongImageSkipped: Boolean(parsed.skipped),
    detailLongImagePath: parsed.detailLongImagePath || defaultPath,
    detailLongImageFileName: parsed.detailLongImageFileName || '详情长图.png',
    detailLongImageWidth: parsed.detailLongImageWidth || 0,
    detailLongImageHeight: parsed.detailLongImageHeight || 0,
    detailLongImageSizeBytes: parsed.detailLongImageSizeBytes || 0,
    detailLongImageInputCount: parsed.inputImageCount || 0,
    detailLongImageInputImages: Array.isArray(parsed.inputImages) ? parsed.inputImages : [],
    detailLongImageResultSource,
    detailLongImageResultPath: parsed.resultFilePath || resultFilePath,
  },
}];

const result = $input.first().json || {};
const normalized = $('Normalize Parameters').first().json || {};
const preflight = $('Parse Idempotency Preflight').first().json || {};

function boundedTextArray(value) {
  return Array.isArray(value)
    ? value.slice(0, 2).map((entry) => String(entry || '').slice(0, 160))
    : [];
}

function compactFailure(value) {
  return {
    success: false,
    status: String(value?.status || 'idempotency_finalize_failed').slice(0, 128),
    httpStatus: Number.isInteger(Number(value?.httpStatus)) ? Number(value.httpStatus) : 500,
    platform: String(value?.platform || 'pdd').slice(0, 32),
    SKU: String(value?.SKU || '').slice(0, 64),
    productName: String(value?.productName || '').slice(0, 256),
    productUrl: String(value?.productUrl || '').slice(0, 1024),
    goodsId: String(value?.goodsId || '').slice(0, 128),
    outputDir: String(value?.outputDir || '').slice(0, 1024),
    mainImageCount: Number(value?.mainImageCount || 0),
    detailImageCount: Number(value?.detailImageCount || 0),
    videoCount: Number(value?.videoCount || 0),
    browserProfileBusy: Boolean(value?.browserProfileBusy),
    browserProfileLocked: Boolean(value?.browserProfileLocked),
    needLoginOrCaptcha: Boolean(value?.needLoginOrCaptcha),
    needHumanVerification: Boolean(value?.needHumanVerification),
    humanVerificationStatus: String(value?.humanVerificationStatus || '').slice(0, 128),
    retryReason: String(value?.retryReason || '').slice(0, 256),
    detailLongImageSuccess: Boolean(value?.detailLongImageSuccess),
    detailLongImageSkipped: Boolean(value?.detailLongImageSkipped),
    errors: boundedTextArray(value?.errors),
    warnings: boundedTextArray(value?.warnings),
  };
}

const ownerN8nExecutionId = String(preflight.ownerN8nExecutionId || result.n8nExecutionId || normalized.n8nExecutionId || '');
const ownerOutputDir = String(preflight.ownerOutputDir || result.outputDir || normalized.expectedOutputDir || '');
const payload = {
  workflowCode: normalized.workflowCode || 'E006',
  isWebhook: Boolean(normalized.isWebhook),
  downloadJobId: normalized.downloadJobId || '',
  requestN8nExecutionId: normalized.n8nExecutionId || '',
  idempotency: preflight.idempotency || { enabled: false },
  resultReference: {
    mode: 'verified_artifacts',
    workflowCode: normalized.workflowCode || 'E006',
    parentOutputDir: normalized.parentOutputDir || '',
    allowedOutputRoots: Array.isArray(normalized.allowedOutputRoots) ? normalized.allowedOutputRoots : [],
    outputDir: ownerOutputDir,
    SKU: normalized.SKU || result.SKU || '',
    productName: normalized.productName || result.productName || '',
    productUrl: normalized.productUrl || result.productUrl || '',
    platformProductId: normalized.goodsId || result.goodsId || '',
    ownerN8nExecutionId,
  },
};
if (result.success !== true) payload.inlineResult = compactFailure(result);
let encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
if (encoded.length > 6000) {
  const overflowPayload = {
    workflowCode: normalized.workflowCode || 'E006',
    isWebhook: Boolean(normalized.isWebhook),
    downloadJobId: normalized.downloadJobId || '',
    ownerN8nExecutionId,
    requestN8nExecutionId: normalized.n8nExecutionId || '',
    idempotency: preflight.idempotency || { enabled: false },
    inlineResult: {
      success: false,
      status: 'idempotency_finalize_payload_too_large',
      httpStatus: 500,
      platform: 'pdd',
      SKU: String(normalized.SKU || '').slice(0, 64),
      productName: String(normalized.productName || '').slice(0, 128),
      outputDir: ownerOutputDir.slice(0, 1024),
      errors: ['Finalize identity exceeded the safe Windows command-line envelope.'],
      warnings: [],
    },
  };
  encoded = Buffer.from(JSON.stringify(overflowPayload), 'utf8').toString('base64');
}
if (encoded.length > 6000) throw new Error('Idempotency finalize context exceeds the safe Windows command-line envelope.');
return [{ json: {
  ...result,
  nodeExecutable: normalized.nodeExecutable || 'node',
  idempotencyHelperScriptPath: normalized.idempotencyHelperScriptPath || '',
  idempotencyFinalizeParamBase64: encoded,
  downloadJobId: normalized.downloadJobId || '',
  ownerN8nExecutionId,
  requestN8nExecutionId: normalized.n8nExecutionId || '',
} }];

const current = $input.first().json || {};
const original = $('Build Idempotency Finalize Params').first().json || {};
const lines = String(current.stdout || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean).reverse();
let parsed = null;
for (const line of lines) {
  try {
    const value = JSON.parse(line);
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      parsed = value;
      break;
    }
  } catch {}
}
if (parsed) return [{ json: parsed }];
const warnings = Array.isArray(original.warnings) ? [...original.warnings] : [];
if (String(current.stderr || '').trim()) warnings.push(String(current.stderr).trim().slice(0, 1000));
return [{ json: {
  ...original,
  success: false,
  status: 'idempotency_finalize_error',
  httpStatus: 500,
  idempotencyState: 'failed',
  idempotencyReplay: false,
  downloadJobId: String(original.downloadJobId || ''),
  ownerN8nExecutionId: String(original.ownerN8nExecutionId || ''),
  requestN8nExecutionId: String(original.requestN8nExecutionId || ''),
  warnings,
  errors: [...(Array.isArray(original.errors) ? original.errors : []), 'Idempotency finalize did not return valid JSON.'],
} }];
